how.python:
def g(n):
    return n ^ (n >> 1)


def rev_g(gcode):
    n = 0
    while gcode:
        n ^= gcode
        gcode >>= 1
    return n


def gray_sequence(k):
    seq = [0]
    for _ in range(k):
        size = len(seq)
        seq = seq + [x | size for x in reversed(seq)]
    return seq


def main():
    # 正向变换 + 相邻汉明距离恒为 1
    vals = [g(n) for n in range(16)]
    for a, b in zip(vals, vals[1:]):
        assert (a ^ b).bit_count() == 1, (a, b)
    assert vals == [0, 1, 3, 2, 6, 7, 5, 4, 12, 13, 15, 14, 10, 11, 9, 8]
    # 逆变换正确性
    for n in range(256):
        assert rev_g(g(n)) == n
    # 镜像法生成的序列与公式一致
    assert gray_sequence(4) == [g(n) for n in range(16)]
    print("gray-code OK")


if __name__ == "__main__":
    main()
